pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, address target, bytes calldata data) public {
        vm.assume(amount > 0);
        vm.assume(target != address(c));
        vm.assume(target != address(this));

        vm.deal(c.Owner(), amount);
        vm.prank(c.Owner());
        uint256 beforeBal = address(c).balance;
        c.Command{value: amount}(target, data);
        uint256 afterBal = address(c).balance;

        uint256 forwarded;
        if (target.balance > 0) {
            forwarded = target.balance;
        } else {
            forwarded = 0;
        }

        assertTrue(afterBal == beforeBal + amount - forwarded);
    }
}

